function parseFilters(allowed, params) {
  const accepted = [];
  const errors = [];
  for (let i = 0; i < params.length; i += 1) {
    const p = params[i];
    if (!Object.prototype.hasOwnProperty.call(allowed, p.field)) {
      errors.push('unknown field: ' + p.field);
      continue;
    }
    const ops = allowed[p.field].ops;
    let permitted = false;
    for (let j = 0; j < ops.length; j += 1) {
      if (ops[j] === p.op) {
        permitted = true;
        break;
      }
    }
    if (!permitted) {
      errors.push('unsupported operator: ' + p.field + '.' + p.op);
      continue;
    }
    accepted.push({ field: p.field, op: p.op, value: p.value });
  }
  return { accepted: accepted, errors: errors };
}

