function classifyChange(before, after) {
  const reasons = [];
  const beforeKeys = Object.keys(before);
  for (let i = 0; i < beforeKeys.length; i += 1) {
    const key = beforeKeys[i];
    if (!Object.prototype.hasOwnProperty.call(after, key)) {
      reasons.push('removed: ' + key);
      continue;
    }
    if (before[key].type !== after[key].type) {
      reasons.push('retyped: ' + key);
    }
    if (before[key].required === false && after[key].required === true) {
      reasons.push('now required: ' + key);
    }
  }
  const afterKeys = Object.keys(after);
  for (let i = 0; i < afterKeys.length; i += 1) {
    const key = afterKeys[i];
    if (Object.prototype.hasOwnProperty.call(before, key)) continue;
    if (after[key].required === true) {
      reasons.push('new required field: ' + key);
    }
  }
  return { verdict: reasons.length > 0 ? 'breaking' : 'compatible', reasons: reasons };
}

