function planRelease(steps) {
  const RANK = {
    'add-column': 0,
    'dual-write': 1,
    'backfill': 2,
    'read-new': 3,
    'drop-column': 4,
  };
  const known = [];
  const unknown = [];
  let hasReadNew = false;
  let hasAddColumn = false;
  for (let i = 0; i < steps.length; i += 1) {
    const s = steps[i];
    if (!Object.prototype.hasOwnProperty.call(RANK, s.phase)) {
      unknown.push('unknown phase: ' + s.id);
      continue;
    }
    if (s.phase === 'read-new') hasReadNew = true;
    if (s.phase === 'add-column') hasAddColumn = true;
    known.push({ id: s.id, phase: s.phase, at: i });
  }
  known.sort(function (a, b) {
    if (RANK[a.phase] !== RANK[b.phase]) return RANK[a.phase] - RANK[b.phase];
    return a.at - b.at;
  });
  const order = [];
  const unsafe = [];
  for (let i = 0; i < known.length; i += 1) {
    const s = known[i];
    order.push(s.id);
    if (s.phase === 'drop-column' && !hasReadNew) {
      unsafe.push('drop before read-new: ' + s.id);
    }
    if (s.phase === 'backfill' && !hasAddColumn) {
      unsafe.push('backfill before column exists: ' + s.id);
    }
  }
  for (let i = 0; i < unknown.length; i += 1) {
    unsafe.push(unknown[i]);
  }
  return { order: order, unsafe: unsafe };
}

